CREATE TABLE roles (id uuid PRIMARY KEY, name text NOT NULL UNIQUE, builtin boolean NOT NULL DEFAULT false);
CREATE TABLE permissions (key text PRIMARY KEY);
INSERT INTO permissions VALUES ('dashboard.read'),('records.read'),('records.create'),('records.edit'),('records.delete'),('updates.trigger'),('providers.read'),('providers.manage'),('credentials.manage'),('users.manage'),('roles.manage'),('history.read'),('audit.read'),('settings.manage'),('backup.create'),('backup.restore'),('tokens.manage');
INSERT INTO roles VALUES ('00000000-0000-0000-0000-000000000001','Administrator',true),('00000000-0000-0000-0000-000000000002','Operator',true),('00000000-0000-0000-0000-000000000003','User',true),('00000000-0000-0000-0000-000000000004','Viewer',true);
CREATE TABLE role_permissions (role_id uuid REFERENCES roles(id) ON DELETE CASCADE, permission text REFERENCES permissions(key), PRIMARY KEY(role_id,permission));
INSERT INTO role_permissions SELECT '00000000-0000-0000-0000-000000000001',key FROM permissions;
