CREATE TABLE users (id uuid PRIMARY KEY, username text NOT NULL UNIQUE CHECK(length(username) BETWEEN 3 AND 80), password_hash text NOT NULL, role_id uuid NOT NULL REFERENCES roles(id), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf_token text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE login_attempts (username text PRIMARY KEY, attempts integer NOT NULL DEFAULT 1, window_start timestamptz NOT NULL DEFAULT now());
CREATE TABLE providers (id uuid PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('hetznercloud','cloudflare')), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120), enabled boolean NOT NULL DEFAULT true, credential_version bigint NOT NULL DEFAULT 1, suspended boolean NOT NULL DEFAULT false, blocked_until timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE provider_credentials (provider_id uuid PRIMARY KEY REFERENCES providers(id) ON DELETE CASCADE, key_id text NOT NULL DEFAULT 'v1', ciphertext bytea NOT NULL);
CREATE TABLE provider_permissions (provider_id uuid REFERENCES providers(id) ON DELETE CASCADE, user_id uuid REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(provider_id,user_id));
CREATE TABLE dns_zones (id uuid PRIMARY KEY, provider_id uuid NOT NULL REFERENCES providers(id), remote_id text NOT NULL, name text NOT NULL, UNIQUE(provider_id,remote_id));
CREATE TABLE dns_records (id uuid PRIMARY KEY, zone_id uuid NOT NULL REFERENCES dns_zones(id), name text NOT NULL, record_type text NOT NULL CHECK(record_type IN ('A','AAAA')), remote_record_id text NOT NULL DEFAULT '', managed_ip text NOT NULL DEFAULT '', manual_ip text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT false, interval_seconds integer NOT NULL DEFAULT 300 CHECK(interval_seconds BETWEEN 60 AND 86400), owner_id uuid NOT NULL REFERENCES users(id), site text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'pending', next_check timestamptz NOT NULL DEFAULT now(), last_check timestamptz, last_update timestamptz, config_version bigint NOT NULL DEFAULT 1, UNIQUE(zone_id,name,record_type));
CREATE TABLE record_permissions (record_id uuid REFERENCES dns_records(id) ON DELETE CASCADE, user_id uuid REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(record_id,user_id));
CREATE TABLE update_jobs (id uuid PRIMARY KEY, record_id uuid NOT NULL REFERENCES dns_records(id) ON DELETE CASCADE, state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','running','done')), trigger text NOT NULL, due_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, attempts integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX update_jobs_one_active ON update_jobs(record_id) WHERE state IN ('queued','running');
CREATE INDEX update_jobs_due ON update_jobs(due_at) WHERE state='queued';
CREATE TABLE update_history (id uuid PRIMARY KEY, record_id uuid REFERENCES dns_records(id) ON DELETE SET NULL, fqdn text NOT NULL, provider_name text NOT NULL, previous_ip text NOT NULL DEFAULT '', new_ip text NOT NULL DEFAULT '', trigger text NOT NULL, outcome text NOT NULL, duration_ms bigint NOT NULL, error_code text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX update_history_time ON update_history(created_at DESC);
CREATE TABLE audit_logs (id uuid PRIMARY KEY, user_id uuid REFERENCES users(id) ON DELETE SET NULL, action text NOT NULL, object_id uuid, created_at timestamptz NOT NULL DEFAULT now());
